function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2500)}
function refresh(){ $('#credz').textContent=state.credz;$('#playerName').textContent=state.name.toUpperCase();$('#playerCourse').textContent=`FIRST YEAR · ${state.course.toUpperCase()}`;$('#profileInitial').textContent=state.name[0].toUpperCase();$('#portrait').textContent=state.name[0].toUpperCase();$('#portrait').style.background=`linear-gradient(145deg,${state.skin},${state.hair})`;$('#xpText').textContent=`${state.xp} / 100 XP`;$('#xpBar').style.width=state.xp+'%';$('#levelText').textContent=String(1+Math.floor(state.xp/100)).padStart(2,'0');for(const n of ['energy','hunger','joy','social']){$('#'+n+'Bar').style.width=state[n]+'%';$('#'+n+'Value').textContent=state[n]}$('#questStep').textContent=`${Math.min(state.quest,3)} / 3 moments`;$('#questBar').style.width=(state.quest/3*100)+'%';$('#questDescription').textContent=['Meet someone on campus','Finish a study session','Find a place to call home'][Math.min(state.quest,2)];$('#dayLabel').textContent=`${['MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY','SUNDAY'][(state.day-1)%7]} · WEEK ${Math.ceil(state.day/7)}`}
function addXP(v){state.xp+=v;if(state.xp>=100)toast('Level up! New opportunities are opening.');refresh()}
const sceneEl=$('#scene');const scene=new THREE.Scene();scene.background=new THREE.Color('#b6d7cd');scene.fog=new THREE.Fog('#b6d7cd',25,90);
const camera=new THREE.PerspectiveCamera(42,1,.1,150);camera.position.set(17,17,23);camera.lookAt(0,0,0);
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;sceneEl.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight('#f5fff0','#759377',2));const sun=new THREE.DirectionalLight('#fff0cb',3.3);sun.position.set(-12,23,10);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);scene.add(sun);
const mat=(color,roughness=.9)=>new THREE.MeshStandardMaterial({color,roughness});
const mats={grass:mat('#a8c987'),grass2:mat('#8fb47b'),path:mat('#e6d6ad'),wood:mat('#956c4c'),cream:mat('#fff1d2'),roof:mat('#d58f6e'),pink:mat('#e8a9bc'),leaf:mat('#79a879'),gold:mat('#e7c56e'),water: new THREE.MeshStandardMaterial({color:'#78c7d1',roughness:.22,metalness:.1,transparent:true,opacity:.88}),white:mat('#fffaf1')};
function box(x,y,z,sx,sy,sz,material){let m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y+sy/2,z);m.castShadow=true;m.receiveShadow=true;scene.add(m);return m}
