function tree(x,z,color='#78a879',size=1){box(x,0,z,.24*size,1.25*size,.24*size,mats.wood);sphere(x,.95*size,z,.8*size,mat(color),1);sphere(x-.36*size,1.2*size,z+.12*size,.48*size,mat(color),1);sphere(x+.33*size,1.35*size,z-.14*size,.46*size,mat(color),1);}
function flower(x,z,color){let stem=box(x,0,z,.035,.28,.035,mat('#68966d'));sphere(x,.32,z,.13,mat(color),1);for(let a=0;a<5;a++){let angle=a*Math.PI*2/5;sphere(x+Math.cos(angle)*.12,.31,z+Math.sin(angle)*.12,.07,mat(color),1)}}
// Soft rolling landscape and winding path
let ground=new THREE.Mesh(new THREE.PlaneGeometry(90,90,20,20),mats.grass);ground.rotation.x=-Math.PI/2;ground.position.y=-.12;ground.receiveShadow=true;scene.add(ground);
