// Campus hall
box(-3,0,-4,7,3.8,4.2,mats.cream);let roof=new THREE.Mesh(new THREE.ConeGeometry(5.1,2.1,4),mats.roof);roof.position.set(.5,4.85,-1.9);roof.rotation.y=Math.PI/4;roof.castShadow=true;scene.add(roof);
for(let x=-5.7;x<.5;x+=1.55){box(x,1.2,-1.86,.72,1.35,.13,mat('#83b7b2'));box(x,1.2,-1.77,.09,1.45,.07,mats.white)}box(-1.6,0,-1.78,1.1,2.1,.18,mats.wood);box(-3,4,-4,.32,.55,.3,mats.gold);
// Library and cafe
box(7,0,-5,4.8,2.7,3.5,mat('#f2dcac'));box(7,2.8,-5,5.1,.25,3.8,mats.roof);box(6.6,0,-3.18,1,1.7,.12,mat('#8bb9b1'));box(8.1,0,-3.18,1,1.7,.12,mat('#8bb9b1'));box(-8,0,2,4.2,2.4,3.3,mat('#e9c2a8'));box(-8,2.5,2,4.5,.4,3.5,mat('#8eaa7a'));box(-8,0,3.7,1,1.45,.1,mat('#b97960'));
// Fountain
let fountainBase=new THREE.Mesh(new THREE.CylinderGeometry(1.3,1.45,.35,12),mat('#e8ddc1'));fountainBase.position.set(1,.17,4);fountainBase.castShadow=true;scene.add(fountainBase);let fountain=new THREE.Mesh(new THREE.CylinderGeometry(.7,.82,.22,12),mats.water);fountain.position.set(1,.42,4);scene.add(fountain);let jet=new THREE.Mesh(new THREE.CylinderGeometry(.08,.14,1.15,8),mats.water);jet.position.set(1,1.08,4);scene.add(jet);sphere(1,1.7,4,.17,mats.water,1);
// Distant waterfall, rocks and stream
for(let i=0;i<8;i++){let x=-16+i*1.25;box(x,2.1,-13,.8,4.2,.65,mat(i%2?'#9cae92':'#8fa28c'))}let fall=new THREE.Mesh(new THREE.PlaneGeometry(4.5,5),mats.water);fall.position.set(-11.5,2.2,-12.5);scene.add(fall);let pool=new THREE.Mesh(new THREE.CylinderGeometry(3,3.5,.15,18),mats.water);pool.position.set(-11.5,.06,-9.5);scene.add(pool);
// Tree groves and flower beds
for(const [x,z,c,s] of [[-13,-5,'#e8a5ba',1.25],[-15,1,'#e8a5ba',1],[-12,8,'#ddb66d',1.1],[12,-12,'#8baa69',1.3],[15,-4,'#e7a3b8',1.2],[11,4,'#a8c776',1.15],[4,12,'#dfba61',1.2],[-7,-12,'#83ad74',1.2],[17,10,'#81a775',1.3],[-17,13,'#e2a7b6',1.15],[3,-12,'#d9b763',1]])tree(x,z,c,s);
for(let i=0;i<65;i++){let x=-15+Math.random()*30,z=-11+Math.random()*25;if(Math.abs(x)<4&&z<1&&z>-8)continue;flower(x,z,['#f2d783','#eaa6b7','#fff2dc','#bdacd5'][i%4])}
// lamp posts + benches
for(const [x,z] of [[-10,-3],[4,7],[11,1],[-3,9]]){box(x,0,z,.11,1.8,.11,mats.wood);sphere(x,1.92,z,.2,mat('#ffe5a0'),1);box(x+.8,0,z+1,.95,.18,.28,mats.wood);box(x+.8,.4,z+1,.95,.14,.12,mats.wood)}
// Player character, low-poly articulated body
const avatar=new THREE.Group();scene.add(avatar);const skinMat=mat(state.skin),shirtMat=mat(state.clothes),pantsMat=mat('#55637a'),hairMat=mat(state.hair);let torso=new THREE.Mesh(new THREE.CapsuleGeometry(.34,.66,3,7),shirtMat);torso.position.y=1.15;torso.castShadow=true;avatar.add(torso);let head=new THREE.Mesh(new THREE.SphereGeometry(.31,10,8),skinMat);head.position.y=1.93;head.castShadow=true;avatar.add(head);let hair=new THREE.Mesh(new THREE.SphereGeometry(.325,10,7,0,Math.PI*2,0,Math.PI*.56),hairMat);hair.position.y=2.02;avatar.add(hair);let legs=[];for(let x of [-.16,.16]){let l=new THREE.Mesh(new THREE.CapsuleGeometry(.13,.5,2,6),pantsMat);l.position.set(x,.47,0);l.castShadow=true;avatar.add(l);legs.push(l)}let arms=[];for(let x of [-.43,.43]){let a=new THREE.Mesh(new THREE.CapsuleGeometry(.105,.47,2,6),skinMat);a.position.set(x,1.23,0);a.rotation.z=x<0?-.12:.12;avatar.add(a);arms.push(a)}avatar.position.set(0,0,7);
