function resize(){let r=sceneEl.getBoundingClientRect();if(!r.width||!r.height)return;renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix()}new ResizeObserver(resize).observe(sceneEl);resize();
let keys={},velocity=0,jumpV=0,clockTime=0;window.addEventListener('keydown',e=>{if(['w','a','s','d',' ','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){keys[e.key.toLowerCase()]=true;if(e.key===' ')e.preventDefault()}});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
function animate(){requestAnimationFrame(animate);let dt=Math.min(.04,clockTime?performance.now()/1000-clockTime:.016);clockTime=performance.now()/1000;if(!state.paused){let speed=state.running?.12:.07;let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dz=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(dx||dz){avatar.position.x+=dx*speed;avatar.position.z+=dz*speed;avatar.rotation.y=Math.atan2(dx,dz);velocity+=dt*12;legs[0].rotation.x=Math.sin(velocity*7)*.55;legs[1].rotation.x=-Math.sin(velocity*7)*.55;arms[0].rotation.x=-legs[0].rotation.x*.6;arms[1].rotation.x=-legs[1].rotation.x*.6}else{legs.forEach(l=>l.rotation.x*=.8);arms.forEach(a=>a.rotation.x*=.8)}if(keys[' ']&&avatar.position.y<.03)jumpV=.22;if(avatar.position.y>0||jumpV>0){avatar.position.y+=jumpV;jumpV-=.009;if(avatar.position.y<0){avatar.position.y=0;jumpV=0}}avatar.position.x=THREE.MathUtils.clamp(avatar.position.x,-19,19);avatar.position.z=THREE.MathUtils.clamp(avatar.position.z,-16,17);camera.position.x=17+avatar.position.x*.22;camera.position.z=23+avatar.position.z*.18;camera.lookAt(avatar.position.x*.12,0,avatar.position.z*.12)}renderer.render(scene,camera)}animate();
