$('#modalClose').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});
function startCharacter(){let hair=['#49352f','#211f26','#d6a64f','#b76543','#74558b','#e9d8bd'],skin=['#f1ceb1','#e5b18d','#bc805f','#80523f','#583c35'],eyes=['#617caa','#68875b','#725849','#765d86'];const sw=(arr,group)=>arr.map((c,i)=>`<button class="swatch ${i===0?'active':''}" style="background:${c}" data-group="${group}" data-color="${c}" aria-label="color"></button>`).join('');openModal('Create your character',`<p class="modal-copy">Every great story starts with you. Choose your look and a course to begin your first year at Willowbrook.</p><div class="modal-grid"><div class="field full"><label>YOUR NAME</label><input id="charName" maxlength="20" value="Alex River"></div><div class="field"><label>PRONOUNS</label><select id="charGender"><option>They</option><option>She</option><option>He</option></select></div><div class="field"><label>COLLEGE STUDY</label><select id="charCourse"><option>Undecided</option><option>Art & Design</option><option>Environmental Science</option><option>Business</option><option>Hospitality</option><option>Computer Science</option></select></div><div class="field full"><label>SKIN TONE</label><div class="swatches">${sw(skin,'skin')}</div></div><div class="field full"><label>HAIR COLOR</label><div class="swatches">${sw(hair,'hair')}</div></div><div class="field full"><label>EYE COLOR</label><div class="swatches">${sw(eyes,'eyes')}</div></div></div>`,[['START MY STORY',()=>{state.name=$('#charName').value.trim()||'Alex River';state.gender=$('#charGender').value;state.course=$('#charCourse').value;let c={skin:state.skin,hair:state.hair,eyes:state.eyes};$$('.swatch.active').forEach(x=>c[x.dataset.group]=x.dataset.color);Object.assign(state,c);skinMat.color.set(state.skin);hairMat.color.set(state.hair);refresh();closeModal();toast('Welcome to Willowbrook! Your story begins.');},'primary']]);$$('.swatch').forEach(b=>b.onclick=()=>{b.parentElement.querySelectorAll('.swatch').forEach(x=>x.classList.remove('active'));b.classList.add('active')})}
$('#profileBtn').onclick=startCharacter;
function progressQuest(){if(state.quest<3){state.quest++;if(state.quest===3)toast('Chapter one complete! Your next chapter awaits.');refresh()}}
