$$('.person-row').forEach(b=>b.onclick=()=>window.makeFriend(b.dataset.person));$('#peopleBtn').onclick=()=>{$$('.tab').find(x=>x.dataset.tab==='people').click()};
function drawMap(){let c=$('#mapCanvas');c.innerHTML='';for(const p of places){let b=document.createElement('button');b.className='map-dot '+(p.id===state.location?'you':'');b.style.left=p.x+'%';b.style.top=p.y+'%';b.textContent=p.id===state.location?'◆':p.icon;b.title=p.name;b.onclick=()=>{if(state.visited.has(p.id)){travel(p.id);$('#miniMap').classList.remove('open')}else toast('Visit this place first to unlock instant travel.')};c.appendChild(b)}}drawMap();
$('#mapBtn').onclick=()=>{$('#miniMap').classList.toggle('open');drawMap()};$('#mapClose').onclick=()=>$('#miniMap').classList.remove('open');$('#travelBtn').onclick=()=>{$('#miniMap').classList.add('open');drawMap()};
function shop(){if(state.location!=='downtown'){travel('downtown')}openModal('Juniper City',`<p class="modal-copy">Pick your vibe: discover genre-inspired storefronts, local cafés, and opportunities around the city.</p><div class="shop-items">${[['🧥','Thread & Thistle','Indie clothing · outfit colors','clothes'],['🍜','Moon Noodle House','Asian comfort food · +hunger','food'],['☕','Velvet Vinyl Café','Coffee, jazz & campus shifts','cafe'],['🌿','The Garden Shelf','Seeds, soil & starter plants','seeds'],['🪨','Mineral Market','Wood, stone & build supplies','materials']].map(([i,n,d,k])=>`<div class="shop-item"><span>${i}</span><div><b>${n}</b><small>${d}</small></div><button onclick="window.buy('${k}')">VISIT</button></div>`).join('')}</div>`)}
window.buy=k=>{closeModal();if(k==='food'){if(state.credz<12){toast('Need 12 credzz for a meal. Pick up a campus shift!');return}state.credz-=12;state.food+=1;state.hunger=Math.min(100,state.hunger+30);refresh();toast('Meal enjoyed · +30 hunger')}if(k==='seeds'){if(state.credz<18){toast('Need 18 credzz for seeds.');return}state.credz-=18;state.seeds+=5;refresh();toast('Five flower seeds added to your bag!')}if(k==='materials'){if(state.credz<25){toast('Need 25 credzz for building supplies.');return}state.credz-=25;state.wood+=6;state.stone+=4;refresh();toast('+6 wood · +4 stone')}if(k==='clothes'){let colors=['#d98c79','#7797ac','#8d78a9','#6c8c72'];state.clothes=colors[Math.floor(Math.random()*colors.length)];shirtMat.color.set(state.clothes);if(state.credz>=20)state.credz-=20;refresh();toast('A fresh outfit! Look at you.')}if(k==='cafe')openModal('A job with a view',`<p class="modal-copy">Sam is looking for a friendly face at the Velvet Vinyl Café. Pick up a shift for <b>45 credzz</b>. Your first job is yours!</p>`,[['TAKE A SHIFT',()=>{state.credz+=45;addXP(10);refresh();closeModal();toast('Shift complete · +45 credzz')} ,'primary']])};
function adoption(){openModal('Paws & Whiskers',`<p class="modal-copy">Every pet deserves a loving home. Meet your new best friend at the Willowbrook adoption center.</p><div class="shop-items"><div class="shop-item"><span>🐕</span><div><b>Sunny · golden pup</b><small>Playful, loyal, loves the garden · 60 credzz</small></div><button onclick="window.adopt('dog')">MEET</button></div><div class="shop-item"><span>🐈</span><div><b>Peaches · little cat</b><small>Curious, cozy, excellent nap companion · 50 credzz</small></div><button onclick="window.adopt('cat')">MEET</button></div></div>`)}window.adopt=pet=>{if(state.pet){toast('Your home already has a new best friend!');return}let cost=pet==='dog'?60:50;if(state.credz<cost){toast(`Save up ${cost} credzz to adopt your pet.`);return}state.credz-=cost;state.pet=true;refresh();closeModal();toast(`Welcome home, ${pet==='dog'?'Sunny':'Peaches'}!`)};$('#petBtn').onclick=adoption;
$('#scheduleBtn').onclick=()=>openModal('Your college journey',`<p class="modal-copy">Your studies shape the careers available to you. Attend class and study to raise your grades.</p><div class="shop-items">${[['📚','Study session','Library · improve grades and XP'],['🎓','Foundations of design','Arts Hall · Monday, 10:00'],['☕','Campus café shift','Flexible hours · +45 credzz'],['🌱','Community garden','Find seeds and help your neighbors']].map(([i,n,d])=>`<div class="shop-item"><span>${i}</span><div><b>${n}</b><small>${d}</small></div></div>`).join('')}</div><p class="modal-copy"><b>Your course:</b> ${state.course} &nbsp;·&nbsp; <b>Current grade:</b> ${state.grade}%</p><p class="modal-copy"><b>Career outlook:</b> ${state.grade>=85?'Honors track unlocked!':state.course==='Art & Design'?'Design studio · illustrator · creative director':state.course==='Environmental Science'?'Park ranger · ecologist · urban gardener':state.course==='Business'?'Entrepreneur · city planner · manager':state.course==='Hospitality'?'Chef · event host · hotel manager':state.course==='Computer Science'?'Game designer · software developer · tech founder':'Choose a college study to discover careers!'}</p>`);
$('#questButton').onclick=()=>openModal('New roots, new routes',`<p class="modal-copy">Your first week at Willowbrook is full of possibilities. Meet a friend, make time for your studies, and find a place that feels like home.</p><div class="shop-items"><div class="shop-item"><span>♡</span><div><b>Meet someone on campus</b><small>${state.quest>0?'Complete':'In progress'}</small></div></div><div class="shop-item"><span>⌑</span><div><b>Finish a study session</b><small>${state.quest>1?'Complete':'In progress'}</small></div></div><div class="shop-item"><span>⌂</span><div><b>Find a place to call home</b><small>${state.quest>2?'Complete':'In progress'}</small></div></div></div>`);

