$('#questButton').onclick=()=>openModal('New roots, new routes',`<p class="modal-copy">Your first week at Willowbrook is full of possibilities. Meet a friend, make time for your studies, and find a place that feels like home.</p><div class="shop-items"><div class="shop-item"><span>♡</span><div><b>Meet someone on campus</b><small>${state.quest>0?'Complete':'In progress'}</small></div></div><div class="shop-item"><span>⌑</span><div><b>Finish a study session</b><small>${state.quest>1?'Complete':'In progress'}</small></div></div><div class="shop-item"><span>⌂</span><div><b>Find a place to call home</b><small>${state.quest>2?'Complete':'In progress'}</small></div></div></div>`);
function building(){if(!state.build){if(state.wood<2||state.stone<1){toast('Gather 2 wood + 1 stone to claim a home lot.');return}state.build=true;state.wood-=2;state.stone--;refresh();$('#buildHud').classList.add('show');$('#buildBtn').classList.add('on');toast('Your grassy home lot is ready! Choose a furnishing.')}openModal('Make a place your own',`<p class="modal-copy">Place furniture and decorations on your lot. Every cozy home starts with one little thing.</p><div class="build-menu"><button class="active" data-item="chair">🪑 Chair · 1 wood</button><button data-item="tree">🌳 Tree · 1 seed</button><button data-item="lamp">💡 Lamp · 1 stone</button><button data-item="garden">🌱 Garden · 1 seed</button></div><div class="shop-items"><div class="shop-item"><span>🪵</span><div><b>Materials in your backpack</b><small>${state.wood} wood · ${state.stone} stone · ${state.seeds} seeds</small></div><button onclick="window.getMaterials()">GATHER</button></div><div class="shop-item"><span>🏡</span><div><b>Customize your home</b><small>Paint, flooring, furniture, appliances & décor</small></div><button onclick="window.decorate()">STYLE</button></div></div>`,[['PLACE ITEM',()=>{closeModal();state.build=true;toast('Choose an item then click the world to place it.');$('#buildHud').classList.add('show')},'primary']]);$$('.build-menu button').forEach(b=>b.onclick=()=>{$$('.build-menu button').forEach(x=>x.classList.remove('active'));b.classList.add('active');window.buildItem=b.dataset.item;toast(`${b.textContent.split('·')[0]} selected · click the lawn`)});window.buildItem='chair'}
window.getMaterials=()=>{state.wood+=3;state.stone+=2;refresh();toast('+3 wood · +2 stone found in a supply box');building()};window.decorate=()=>openModal('Style your space',`<p class="modal-copy">Make your starter home feel like yours. Pick a look for your rooms.</p><div class="modal-grid"><div class="field"><label>WALL PAINT</label><select onchange="window.paintHome(this.value)"><option value="#fff1d2">Warm cream</option><option value="#d5e5db">Sage green</option><option value="#f0d7dc">Blush pink</option><option value="#d7e4f0">Cloud blue</option></select></div><div class="field"><label>FLOORING</label><select><option>Honey oak</option><option>Soft carpet</option><option>Stone tile</option></select></div><div class="field"><label>CEILING</label><select><option>Cloud white</option><option>Buttercream</option><option>Soft sage</option></select></div><div class="field"><label>APPLIANCES</label><select><option>Starter kitchen</option><option>Cozy cooker</option><option>Deluxe range · 50 credzz</option></select></div></div>`,[['SAVE MY STYLE',()=>{closeModal();toast('Your home style is saved!')},'primary']],'HOME · PERSONALIZE');window.paintHome=color=>{mats.cream.color.set(color);toast('Fresh paint selected!')};
$('#buildBtn').onclick=building;$('#exitBuild').onclick=()=>{state.build=false;$('#buildHud').classList.remove('show');toast('Build saved · your place is coming together!');progressQuest()};sceneEl.addEventListener('pointerdown',e=>{if(!state.build||!window.buildItem)return;let r=renderer.domElement.getBoundingClientRect();let x=(e.clientX-r.left)/r.width*2-1,y=-(e.clientY-r.top)/r.height*2+1;let ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2(x,y),camera);let hit=ray.intersectObject(ground);if(!hit.length)return;let p=hit[0].point;let type=window.buildItem;if(type==='chair'){box(p.x,0,p.z,.7,.62,.7,mat('#c99672'));box(p.x,0,p.z+.25,.7,.14,.18,mat('#b98361'));if(state.wood<1){toast('Need 1 wood.');return}state.wood--}if(type==='tree'){if(state.seeds<1){toast('Need one seed.');return}state.seeds--;tree(p.x,p.z,'#e6a8b7',.8)}if(type==='lamp'){if(state.stone<1){toast('Need 1 stone.');return}state.stone--;box(p.x,0,p.z,.12,1.8,.12,mats.wood);sphere(p.x,1.9,p.z,.24,mat('#ffdf8b'))}if(type==='garden'){if(state.seeds<1){toast('Need one seed.');return}state.seeds--;box(p.x,0,p.z,1.5,.12,1.5,mat('#8b6846'));for(let i=0;i<5;i++)flower(p.x-.5+Math.random(),p.z-.5+Math.random(),'#e8a9bc')}state.placed.push(type);refresh();toast(`${type} placed!`)});
$$('.quick-nav button').forEach(b=>b.onclick=()=>{let p=b.dataset.panel;if(p==='home'){if(state.wood>=2&&state.stone>=1)building();else openModal('Find a place to call home',`<p class="modal-copy">Claim a sunny grassy lot to build your dream home. Scavenge supply boxes around town for the materials you need.</p><div class="shop-items"><div class="shop-item"><span>🪵</span><div><b>Your backpack</b><small>${state.wood} wood · ${state.stone} stone · ${state.seeds} seeds</small></div></div></div>`,[['SEARCH FOR SUPPLIES',()=>{state.wood+=2;state.stone+=1;closeModal();toast('Supply box found · +2 wood +1 stone');building()},'primary']])}if(p==='inventory')openModal('Your backpack',`<div class="shop-items">${[['🪵','Wood',state.wood],['🪨','Stone',state.stone],['🌱','Seeds',state.seeds],['🍎','Food',state.food],['🪑','Home furnishings',state.placed.length]].map(([i,n,v])=>`<div class="shop-item"><span>${i}</span><div><b>${n}</b><small>Ready to use</small></div><button>${v}</button></div>`).join('')}</div>`);if(p==='phone')openModal('Phone & friends',`<p class="modal-copy">Your people make this place home. Friendships grow with a little time together.</p><div class="phone-list">${['Maya Chen','Leo Brooks','Sam Rivera'].map(n=>`<div class="phone-entry"><span class="person-avatar ${n[0]==='M'?'maya':n[0]==='L'?'leo':'sam'}">${n[0]}</span><div><b>${n}</b><small>${state.friends.has(n.split(' ')[0].toLowerCase())?'Friend · online':'New acquaintance'}</small></div></div>`).join('')}</div><div class="shop-items" style="margin-top:10px"><div class="shop-item"><span>✦</span><div><b>Host a little party</b><small>Invite your friends over · +happiness</small></div><button onclick="window.party()">HOST</button></div></div>`)});
window.party=()=>{state.joy=Math.min(100,state.joy+20);state.social=Math.min(100,state.social+15);refresh();closeModal();toast('Best little party ever! Your friends loved it.')};$('#moreBtn').onclick=shop;

